import{_ as n,o as s,c as t,a3 as e}from"./chunks/framework.BlfGB29P.js";const b=JSON.parse('{"title":"从需求到上线：完整案例","description":"","frontmatter":{"title":"从需求到上线：完整案例","outline":[2,3],"article":{"type":"project","structure":"project"}},"headers":[],"relativePath":"frontend/practices/methodology.md","filePath":"frontend/practices/methodology.md","lastUpdated":1785666337000}'),p={name:"frontend/practices/methodology.md"};function l(i,a,r,d,c,o){return s(),t("div",null,[...a[0]||(a[0]=[e(`<h1 id="从需求到上线-完整案例" tabindex="-1">从需求到上线：完整案例 <a class="header-anchor" href="#从需求到上线-完整案例" aria-label="Permalink to &quot;从需求到上线：完整案例&quot;">​</a></h1><blockquote><p>作者：codex-gpt-sol-5.6</p></blockquote><p>这一组不先讲一套抽象流程，而是跟随一个前端需求，看它怎样从一句话变成可验收、可实现、可上线的功能。后续四篇会继续使用同一个案例，并给出实际产物。</p><h2 id="原始需求" tabindex="-1">原始需求 <a class="header-anchor" href="#原始需求" aria-label="Permalink to &quot;原始需求&quot;">​</a></h2><p>某个 Vue 3 运营后台已经有订单列表，产品提出：</p><blockquote><p>给订单列表增加全选和导出 Excel，月底运营要用。</p></blockquote><p>如果直接开发，至少有五个问题没有答案：</p><ul><li>“全选”是当前页，还是当前筛选条件下的全部订单？</li><li>一次可能导出多少条，浏览器能否承担生成文件的内存开销？</li><li>导出期间用户关闭页面，任务是否继续？</li><li>不同角色能导出哪些字段，文件链接能否转发？</li><li>怎样判断功能成功：按钮可点击，还是运营真的拿到了正确文件？</li></ul><p>这些问题会改变交互、状态、接口和权限设计。项目落地的第一步不是创建组件，而是把歧义变成可以决定和验证的问题。</p><h2 id="最终要交付什么" tabindex="-1">最终要交付什么 <a class="header-anchor" href="#最终要交付什么" aria-label="Permalink to &quot;最终要交付什么&quot;">​</a></h2><p>经过澄清，本次项目的结果定义如下：</p><table tabindex="0"><thead><tr><th>项目</th><th>确认结果</th></tr></thead><tbody><tr><td>使用者</td><td>财务运营和区域运营</td></tr><tr><td>用户任务</td><td>按筛选条件导出订单，用于月底对账</td></tr><tr><td>数据规模</td><td>常见 2,000～20,000 条，极端约 100,000 条</td></tr><tr><td>选择语义</td><td>支持“当前页全选”和“选中全部筛选结果”，两者必须明确区分</td></tr><tr><td>执行方式</td><td>少量数据直接下载；大数据量创建异步导出任务</td></tr><tr><td>权限边界</td><td>前端只展示服务端允许的字段和操作，最终权限由服务端校验</td></tr><tr><td>成功标准</td><td>用户能看到进度、失败原因，并在完成后获得仍然有效的下载入口</td></tr><tr><td>非目标</td><td>本期不改造订单查询和角色模型，不实现浏览器端 Excel 生成器</td></tr></tbody></table><p>注意，这里没有承诺服务端如何生成文件。前端只依赖导出任务的接口契约、状态语义和权限结果。</p><h2 id="交付链路" tabindex="-1">交付链路 <a class="header-anchor" href="#交付链路" aria-label="Permalink to &quot;交付链路&quot;">​</a></h2><p>整个项目被整理为五个相互衔接的步骤：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>模糊需求</span></span>
<span class="line"><span>  │</span></span>
<span class="line"><span>  ▼</span></span>
<span class="line"><span>需求澄清与验收标准</span></span>
<span class="line"><span>  │  产出：范围、场景、Given-When-Then</span></span>
<span class="line"><span>  ▼</span></span>
<span class="line"><span>技术方案与评审</span></span>
<span class="line"><span>  │  产出：数据流、状态模型、接口契约、决策记录</span></span>
<span class="line"><span>  ▼</span></span>
<span class="line"><span>拆解与风险验证</span></span>
<span class="line"><span>  │  产出：纵向切片、技术探针、交付预测</span></span>
<span class="line"><span>  ▼</span></span>
<span class="line"><span>迭代交付与上线</span></span>
<span class="line"><span>  │  产出：可运行增量、灰度、监控、回滚</span></span>
<span class="line"><span>  ▼</span></span>
<span class="line"><span>生产验证与复盘</span></span>
<span class="line"><span>     产出：目标数据、问题证据、改进行动</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br></div></div><p>这不是瀑布流程。接口探针可能推翻技术方案，灰度数据也可能暴露需求定义错误。任何阶段得到新证据，都允许回到前面修正。</p><h2 id="第一步-把需求变成验收标准" tabindex="-1">第一步：把需求变成验收标准 <a class="header-anchor" href="#第一步-把需求变成验收标准" aria-label="Permalink to &quot;第一步：把需求变成验收标准&quot;">​</a></h2><p>团队先确认“全选”的两种语义，并把关键场景写成可测试结果：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Given 当前筛选条件匹配 18,420 条订单</span></span>
<span class="line"><span>And 用户只加载了第一页 100 条</span></span>
<span class="line"><span>When 用户选择“全部 18,420 条”并确认导出</span></span>
<span class="line"><span>Then 页面创建一个导出任务，而不是把 18,420 条数据加载到浏览器</span></span>
<span class="line"><span>And 用户离开页面再回来后仍能看到任务进度</span></span>
<span class="line"><span>And 完成后显示文件有效期和下载入口</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p>这段验收标准直接排除了“把所有订单请求到前端，再用 JavaScript 生成 Excel”的实现。需求澄清开始影响技术决策，而不只是补充文档。</p><p>详细过程见<a href="/frontend/practices/methodology/problem-definition">需求澄清与验收标准</a>。</p><h2 id="第二步-确定前端状态与接口边界" tabindex="-1">第二步：确定前端状态与接口边界 <a class="header-anchor" href="#第二步-确定前端状态与接口边界" aria-label="Permalink to &quot;第二步：确定前端状态与接口边界&quot;">​</a></h2><p>前端需要区分三类状态：</p><table tabindex="0"><thead><tr><th>状态</th><th>示例</th><th>所有者</th></tr></thead><tbody><tr><td>查询状态</td><td>筛选条件、排序、页码</td><td>页面，可同步到 URL</td></tr><tr><td>选择状态</td><td>当前页 ID、是否选择全部筛选结果、排除项</td><td>页面会话</td></tr><tr><td>导出任务</td><td>任务 ID、进度、状态、下载地址</td><td>服务端为真实来源，前端查询和展示</td></tr></tbody></table><p>关键数据流是：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>筛选条件 + 选择语义</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>        ▼</span></span>
<span class="line"><span>POST /export-jobs ──► 返回 jobId</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>        ▼</span></span>
<span class="line"><span>轮询 GET /export-jobs/:id</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>        ├─ pending/running ─► 更新进度</span></span>
<span class="line"><span>        ├─ failed ──────────► 显示可操作的失败原因</span></span>
<span class="line"><span>        └─ completed ───────► 显示文件有效期与下载入口</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br></div></div><p>方案必须说明刷新恢复、重复提交、任务取消、下载地址过期和 401/403 的行为。只画正常流程，不足以进入开发。</p><p>完整设计见<a href="/frontend/practices/methodology/technical-design">技术方案、评审与决策记录</a>。</p><h2 id="第三步-先验证最危险的假设" tabindex="-1">第三步：先验证最危险的假设 <a class="header-anchor" href="#第三步-先验证最危险的假设" aria-label="Permalink to &quot;第三步：先验证最危险的假设&quot;">​</a></h2><p>团队没有先做完整弹窗，而是先验证三个高风险问题：</p><ol><li>导出任务接口能否使用筛选快照，避免导出期间数据变化导致结果不一致。</li><li>同一个幂等键重复提交时，是否只创建一个任务。</li><li>页面刷新后，能否根据用户身份恢复未完成任务。</li></ol><p>这些验证可以用临时页面、接口脚本或 Mock 完成。它们的目标不是生产代码，而是在投入大量组件开发前，让关键假设获得证据。</p><p>随后再按可运行结果拆分：</p><ol><li>创建任务并显示状态。</li><li>恢复任务、处理失败与重试。</li><li>接入选择语义、权限和下载。</li><li>补齐监控、灰度与回滚。</li></ol><p>具体方法见<a href="/frontend/practices/methodology/estimation-risk">拆解、估算与风险验证</a>。</p><h2 id="第四步-用真实链路交付" tabindex="-1">第四步：用真实链路交付 <a class="header-anchor" href="#第四步-用真实链路交付" aria-label="Permalink to &quot;第四步：用真实链路交付&quot;">​</a></h2><p>首个迭代不是“完成弹窗组件”，而是让内部账号在测试环境完成一次真实导出。后续迭代逐步增加全部筛选结果、任务恢复和异常处理。</p><p>发布时使用功能开关，仅向内部运营开放。继续放量的条件提前定义：</p><ul><li>创建任务成功率不低于 99%。</li><li>前端没有因轮询产生持续请求或内存增长。</li><li>401、403、任务失败和链接过期都有明确反馈。</li><li>导出字段、数量和当前筛选条件一致。</li></ul><p>如果错误率超过阈值，关闭入口即可停止新任务；已经创建的任务仍能在任务中心查看。这比“出问题就回滚”更具体。</p><h2 id="第五步-用结果完成项目" tabindex="-1">第五步：用结果完成项目 <a class="header-anchor" href="#第五步-用结果完成项目" aria-label="Permalink to &quot;第五步：用结果完成项目&quot;">​</a></h2><p>灰度一周后的数据如下：</p><table tabindex="0"><thead><tr><th>指标</th><th style="text-align:right;">上线前</th><th style="text-align:right;">上线后</th><th>结论</th></tr></thead><tbody><tr><td>月底单次数据整理中位耗时</td><td style="text-align:right;">18 分钟</td><td style="text-align:right;">5 分钟</td><td>达到 6 分钟以内的目标</td></tr><tr><td>导出任务成功率</td><td style="text-align:right;">无</td><td style="text-align:right;">99.4%</td><td>达到 99% 门槛</td></tr><tr><td>重复创建任务比例</td><td style="text-align:right;">无</td><td style="text-align:right;">2.1%</td><td>未达到低于 0.5% 的预期</td></tr><tr><td>下载链接过期相关咨询</td><td style="text-align:right;">无</td><td style="text-align:right;">17 次</td><td>交互提示不足</td></tr></tbody></table><p>项目没有因为“功能上线”就结束。团队从数据中得到两个行动项：</p><ul><li>在提交期间禁用重复操作，并复用相同幂等键，负责人在下一迭代验证重复率。</li><li>在完成通知和下载按钮旁显示到期时间，记录链接过期后的重新生成行为。</li></ul><p>行动项包含问题证据、修改内容和验证指标，而不是“加强测试”“优化体验”。</p><h2 id="阅读这组文章时要完成什么" tabindex="-1">阅读这组文章时要完成什么 <a class="header-anchor" href="#阅读这组文章时要完成什么" aria-label="Permalink to &quot;阅读这组文章时要完成什么&quot;">​</a></h2><p>读完每篇后，读者应该能得到一个可直接检查的产物：</p><table tabindex="0"><thead><tr><th>文章</th><th>应得到的能力</th></tr></thead><tbody><tr><td><a href="/frontend/practices/methodology/problem-definition">需求澄清与验收标准</a></td><td>把一句需求改写成范围明确、可以测试的问题</td></tr><tr><td><a href="/frontend/practices/methodology/technical-design">技术方案、评审与决策记录</a></td><td>用数据流、状态、接口和失败路径解释方案</td></tr><tr><td><a href="/frontend/practices/methodology/estimation-risk">拆解、估算与风险验证</a></td><td>找出高风险未知，并拆成可独立验证的增量</td></tr><tr><td><a href="/frontend/practices/methodology/delivery-ownership">迭代交付、上线与复盘</a></td><td>定义灰度、停止、回滚和结果验证方式</td></tr></tbody></table><p>方法本身不是目的。只有这些产物真的改变实现选择、提前暴露风险，并帮助团队验证结果，它们才有价值。</p>`,51)])])}const u=n(p,[["render",l]]);export{b as __pageData,u as default};
